from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def extract_invoice_fields(file_path, endpoint, api_key):
    credential = AzureKeyCredential(api_key)
    client = DocumentAnalysisClient(endpoint=endpoint, credential=credential)

    with open(file_path, "rb") as document:
        poller = client.begin_analyze_document("prebuilt-invoice", document=document)
        result = poller.result()

    extracted_data = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": []
    }

    for doc in result.documents:
        fields = doc.fields

        vendor_name = fields.get("VendorName")
        if vendor_name:
            extracted_data["vendor"] = vendor_name.value

        invoice_date = fields.get("InvoiceDate")
        if invoice_date and invoice_date.value:
            extracted_data["date"] = str(invoice_date.value)

        invoice_total = fields.get("InvoiceTotal")
        if invoice_total and invoice_total.value:
            extracted_data["total"] = float(invoice_total.value)

        items = fields.get("Items")
        if items and items.value:
            for item in items.value:
                line_item = {}
                if item.value:
                    for field_name, field_val in item.value.items():
                        line_item[field_name] = field_val.value if field_val else None
                extracted_data["line_items"].append(line_item)

    return extracted_data
